SELECT rc.loan_id, rc.as_of_date FROM risk_classification rc JOIN classification_grade g ON g.grade_code = rc.grade_code WHERE g.grade_name_zh = '次级' ORDER BY rc.loan_id;	bankreg_main
SELECT ld.loan_id, ld.disbursed_amount FROM loan_drawdown ld JOIN status_catalog s ON s.entity = 'loan_drawdown' AND s.status_code = ld.status WHERE s.name_zh = '已核销' ORDER BY ld.loan_id;	bankreg_main
SELECT card_id, issued_on, expires_on FROM payment_card WHERE card_type = 'CREDIT' ORDER BY issued_on, card_id;	bankreg_main
SELECT wp.product_name, ROUND(SUM(phs.fair_value), 2) AS total_fair_value FROM product_holding_snapshot phs JOIN wealth_product wp ON wp.product_id = phs.product_id GROUP BY wp.product_id, wp.product_name ORDER BY total_fair_value DESC, wp.product_name LIMIT 10;	bankreg_main
SELECT ou.org_unit_id, ou.unit_name, COUNT(*) AS relation_count FROM party_relation pr JOIN party p ON p.party_id = pr.source_party_id JOIN organization_unit ou ON ou.org_unit_id = p.home_org_unit_id GROUP BY ou.org_unit_id, ou.unit_name ORDER BY relation_count DESC, ou.org_unit_id;	bankreg_main
SELECT i.institution_name, ROUND(AVG(d.principal_overdue_days), 2) AS avg_overdue_days FROM delinquency_snapshot d JOIN loan_drawdown ld ON ld.loan_id = d.loan_id JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN institution i ON i.institution_id = a.institution_id GROUP BY i.institution_id, i.institution_name HAVING AVG(d.principal_overdue_days) > 90 ORDER BY avg_overdue_days DESC, i.institution_name;	bankreg_main
SELECT eg.exposure_group_id, eg.group_name,        ROUND(SUM(lbs.principal_balance), 2) AS exposure_amount,        ROUND(SUM(lbs.principal_balance) * 1.0 / cs.net_capital, 6) AS exposure_ratio FROM exposure_group_member egm JOIN exposure_group eg ON eg.exposure_group_id = egm.exposure_group_id JOIN credit_agreement a ON a.borrower_party_id = egm.party_id JOIN loan_drawdown ld ON ld.agreement_id = a.agreement_id JOIN loan_balance_snapshot lbs ON lbs.loan_id = ld.loan_id JOIN capital_snapshot cs ON cs.institution_id = eg.institution_id GROUP BY eg.exposure_group_id, eg.group_name, cs.net_capital ORDER BY exposure_ratio DESC, eg.exposure_group_id;	bankreg_main
SELECT s.sector_name_zh, COUNT(*) AS loan_count,        SUM(CASE WHEN g.is_nonperforming = 1 THEN 1 ELSE 0 END) AS npl_count,        ROUND(SUM(CASE WHEN g.is_nonperforming = 1 THEN 1 ELSE 0 END) * 1.0 / COUNT(*), 6) AS npl_ratio FROM risk_classification rc JOIN classification_grade g ON g.grade_code = rc.grade_code JOIN loan_drawdown ld ON ld.loan_id = rc.loan_id JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN organization_profile op ON op.party_id = a.borrower_party_id JOIN industry_sector s ON s.sector_code = op.industry_code GROUP BY s.sector_code, s.sector_name_zh HAVING COUNT(*) >= 20 ORDER BY npl_ratio DESC, s.sector_name_zh;	bankreg_main
SELECT p.party_id, p.display_name, ROUND(SUM(a.contract_amount), 2) AS total_contract FROM credit_agreement a JOIN party p ON p.party_id = a.borrower_party_id GROUP BY p.party_id, p.display_name ORDER BY total_contract DESC, p.party_id LIMIT 15;	bankreg_main
SELECT risk_level, COUNT(*) AS product_count,        ROUND(AVG(management_fee_rate), 6) AS avg_fee_rate FROM wealth_product GROUP BY risk_level ORDER BY risk_level;	bankreg_main
SELECT gc.guarantor_party_id, p.display_name,        ROUND(SUM(gc.guaranteed_amount), 2) AS total_guaranteed FROM guarantor_commitment gc JOIN party p ON p.party_id = gc.guarantor_party_id WHERE gc.status = 'ACTIVE' GROUP BY gc.guarantor_party_id, p.display_name HAVING SUM(gc.guaranteed_amount) > 500000000 ORDER BY total_guaranteed DESC, gc.guarantor_party_id;	bankreg_main
SELECT i.institution_name, ROUND(cs.net_capital * 1.0 / cs.risk_weighted_assets, 6) AS car FROM capital_snapshot cs JOIN institution i ON i.institution_id = cs.institution_id ORDER BY car, i.institution_name;	bankreg_main
SELECT i.institution_name, ROUND(SUM(lbs.principal_balance), 2) AS under_prov_balance FROM provision_snapshot ps JOIN loan_balance_snapshot lbs ON lbs.loan_id = ps.loan_id JOIN loan_drawdown ld ON ld.loan_id = ps.loan_id JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN institution i ON i.institution_id = a.institution_id WHERE ps.recognized_amount < ps.required_amount GROUP BY i.institution_id, i.institution_name HAVING SUM(lbs.principal_balance) > 100000000 ORDER BY under_prov_balance DESC, i.institution_name;	bankreg_main
SELECT pi.instruction_id, pi.loan_id, p.display_name, s.sector_name_zh, pi.instruction_amount FROM payment_instruction pi JOIN organization_profile op ON op.party_id = pi.intended_payee_party_id JOIN industry_sector s ON s.sector_code = op.industry_code JOIN party p ON p.party_id = pi.intended_payee_party_id WHERE s.risk_category IN ('RESTRICTED', 'EXIT')   AND pi.status = 'EXECUTED' ORDER BY pi.instruction_amount DESC, pi.instruction_id;	bankreg_main
SELECT wp.product_id, wp.product_name, ma.asset_id, ma.maturity_on, wp.actual_termination_on FROM product_holding_snapshot phs JOIN wealth_product wp ON wp.product_id = phs.product_id JOIN managed_asset ma ON ma.asset_id = phs.asset_id WHERE ma.maturity_on > wp.actual_termination_on ORDER BY ma.maturity_on DESC, wp.product_id, ma.asset_id;	bankreg_main
SELECT i.institution_name, COUNT(*) AS large_cash_count,        ROUND(SUM(pe.amount), 2) AS total_amount FROM payment_event pe JOIN account ac ON ac.account_id = COALESCE(pe.from_account_id, pe.to_account_id) JOIN institution i ON i.institution_id = ac.institution_id WHERE pe.is_cash = 1 AND pe.amount > 5000000 GROUP BY i.institution_id, i.institution_name HAVING COUNT(*) >= 50 ORDER BY total_amount DESC, i.institution_name;	bankreg_main
SELECT so.staff_id, COUNT(*) AS restricted_txn_count FROM payment_event pe JOIN service_operator so ON so.operator_id = pe.operator_id JOIN account_holder ah ON ah.account_id = pe.to_account_id AND ah.holder_role = 'PRIMARY' JOIN organization_profile op ON op.party_id = ah.party_id JOIN industry_sector s ON s.sector_code = op.industry_code WHERE s.risk_category IN ('RESTRICTED', 'EXIT') GROUP BY so.staff_id ORDER BY restricted_txn_count DESC, so.staff_id LIMIT 10;	bankreg_main
SELECT sa.security_id, cl.collateral_id, ca.status AS collateral_status, sa.status AS security_status FROM security_agreement sa JOIN collateral_link cl ON cl.security_id = sa.security_id JOIN collateral_asset ca ON ca.collateral_id = cl.collateral_id WHERE ca.status = 'RELEASED' AND sa.status = 'ACTIVE' ORDER BY sa.security_id;	bankreg_main
SELECT ld.loan_id, a.agreement_id, sa.security_id, sa.secured_amount FROM loan_drawdown ld JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN secured_obligation so ON so.agreement_id = a.agreement_id JOIN security_agreement sa ON sa.security_id = so.security_id WHERE ld.status = 'WRITTEN_OFF' AND sa.status = 'ACTIVE' ORDER BY sa.secured_amount DESC, ld.loan_id;	bankreg_main
WITH ranked AS (     SELECT s.sector_name_zh, lbs.loan_id, lbs.principal_balance,            RANK() OVER (PARTITION BY s.sector_code ORDER BY lbs.principal_balance DESC) AS rnk     FROM loan_balance_snapshot lbs     JOIN loan_drawdown ld ON ld.loan_id = lbs.loan_id     JOIN credit_agreement a ON a.agreement_id = ld.agreement_id     JOIN organization_profile op ON op.party_id = a.borrower_party_id     JOIN industry_sector s ON s.sector_code = op.industry_code ) SELECT sector_name_zh, loan_id, principal_balance, rnk FROM ranked WHERE rnk <= 3 ORDER BY sector_name_zh, rnk, loan_id;	bankreg_main
WITH daily AS (     SELECT business_date, COUNT(*) AS txn_count     FROM payment_event     GROUP BY business_date ) SELECT business_date, txn_count,        txn_count - LAG(txn_count) OVER (ORDER BY business_date) AS delta FROM daily ORDER BY business_date;	bankreg_main
SELECT i.institution_name, lbs.loan_id, lbs.principal_balance,        ROUND((SELECT AVG(lbs2.principal_balance)               FROM loan_balance_snapshot lbs2               JOIN loan_drawdown ld2 ON ld2.loan_id = lbs2.loan_id               JOIN credit_agreement a2 ON a2.agreement_id = ld2.agreement_id               WHERE a2.institution_id = a.institution_id), 2) AS inst_avg,        ROUND(lbs.principal_balance - (SELECT AVG(lbs3.principal_balance)               FROM loan_balance_snapshot lbs3               JOIN loan_drawdown ld3 ON ld3.loan_id = lbs3.loan_id               JOIN credit_agreement a3 ON a3.agreement_id = ld3.agreement_id               WHERE a3.institution_id = a.institution_id), 2) AS excess FROM loan_balance_snapshot lbs JOIN loan_drawdown ld ON ld.loan_id = lbs.loan_id JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN institution i ON i.institution_id = a.institution_id WHERE lbs.principal_balance > (SELECT AVG(lbs4.principal_balance)                               FROM loan_balance_snapshot lbs4                               JOIN loan_drawdown ld4 ON ld4.loan_id = lbs4.loan_id                               JOIN credit_agreement a4 ON a4.agreement_id = ld4.agreement_id                               WHERE a4.institution_id = a.institution_id) ORDER BY excess DESC, lbs.loan_id;	bankreg_main
SELECT cv.collateral_id, cv.valued_on, COUNT(*) AS duplicate_count FROM collateral_valuation cv GROUP BY cv.collateral_id, cv.valued_on HAVING COUNT(*) > 1 ORDER BY cv.collateral_id;	bankreg_main
SELECT p.customer_segment, COUNT(*) AS customer_count,        ROUND(AVG(pp.annual_income), 2) AS avg_income,        ROUND(SUM(CASE WHEN pp.annual_income > 1000000 THEN 1 ELSE 0 END) * 1.0 / COUNT(*), 6) AS high_income_ratio FROM party p JOIN person_profile pp ON pp.party_id = p.party_id WHERE p.party_type = 'INDIVIDUAL' GROUP BY p.customer_segment ORDER BY p.customer_segment;	bankreg_main
WITH txn AS (     SELECT i.institution_id, i.institution_name, pe.amount,            CASE WHEN EXISTS (                SELECT 1 FROM account_holder ah1                JOIN account_holder ah2 ON ah2.account_id = pe.to_account_id AND ah2.holder_role = 'PRIMARY'                JOIN party_relation pr ON pr.source_party_id = ah1.party_id AND pr.target_party_id = ah2.party_id                WHERE ah1.account_id = pe.from_account_id AND pr.relation_type <> 'NON_RELATED'            ) THEN 1 ELSE 0 END AS is_related     FROM payment_event pe     JOIN account ac ON ac.account_id = COALESCE(pe.from_account_id, pe.to_account_id)     JOIN institution i ON i.institution_id = ac.institution_id ) SELECT institution_name,        ROUND(SUM(CASE WHEN is_related = 1 THEN amount ELSE 0 END), 2) AS related_amount,        ROUND(SUM(amount), 2) AS total_amount,        ROUND(SUM(CASE WHEN is_related = 1 THEN amount ELSE 0 END) * 1.0 / SUM(amount), 8) AS related_ratio FROM txn GROUP BY institution_id, institution_name ORDER BY related_ratio DESC, institution_name;	bankreg_main
SELECT loan_id, principal_balance, quartile FROM (     SELECT loan_id, principal_balance,            NTILE(4) OVER (ORDER BY principal_balance DESC) AS quartile     FROM loan_balance_snapshot ) ORDER BY quartile, principal_balance DESC, loan_id LIMIT 40;	bankreg_main
SELECT p.party_id, p.display_name, COUNT(DISTINCT ac.institution_id) AS inst_count FROM account_holder ah JOIN account ac ON ac.account_id = ah.account_id JOIN party p ON p.party_id = ah.party_id WHERE p.party_type = 'INDIVIDUAL' GROUP BY p.party_id, p.display_name HAVING COUNT(DISTINCT ac.institution_id) >= 2 ORDER BY inst_count DESC, p.party_id;	bankreg_main
SELECT i.institution_name, COUNT(DISTINCT egm.party_id) AS member_count,        ROUND(SUM(lbs.principal_balance), 2) AS total_balance FROM exposure_group eg JOIN exposure_group_member egm ON egm.exposure_group_id = eg.exposure_group_id JOIN credit_agreement a ON a.borrower_party_id = egm.party_id AND a.institution_id = eg.institution_id JOIN loan_drawdown ld ON ld.agreement_id = a.agreement_id JOIN loan_balance_snapshot lbs ON lbs.loan_id = ld.loan_id JOIN institution i ON i.institution_id = eg.institution_id GROUP BY i.institution_id, i.institution_name ORDER BY total_balance DESC, i.institution_name;	bankreg_main
SELECT gc.guarantor_party_id, p.display_name, COUNT(DISTINCT gc.security_id) AS security_count,        ROUND(SUM(gc.guaranteed_amount), 2) AS total_guaranteed FROM guarantor_commitment gc JOIN party p ON p.party_id = gc.guarantor_party_id GROUP BY gc.guarantor_party_id, p.display_name HAVING COUNT(DISTINCT gc.security_id) >= 2 AND SUM(gc.guaranteed_amount) > 300000000 ORDER BY total_guaranteed DESC, gc.guarantor_party_id;	bankreg_main
SELECT i.institution_name, COUNT(*) AS cnt FROM loan_drawdown ld JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN institution i ON i.institution_id = a.institution_id WHERE ld.payment_mode = 'ENTRUSTED_PAYMENT' AND ld.status = 'ACTIVE' GROUP BY i.institution_id, i.institution_name ORDER BY cnt DESC, i.institution_name;	bankreg_main
SELECT ld.loan_id, pb.display_name AS borrower, pi.instruction_amount,        pp.display_name AS payee FROM payment_instruction pi JOIN loan_drawdown ld ON ld.loan_id = pi.loan_id JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN party pb ON pb.party_id = a.borrower_party_id JOIN party pp ON pp.party_id = pi.intended_payee_party_id WHERE pi.payment_mode = 'ENTRUSTED_PAYMENT'   AND pi.intended_payee_party_id = a.borrower_party_id ORDER BY pi.instruction_amount DESC, pi.instruction_id LIMIT 200;	bankreg_main
SELECT ld.loan_id, lpc.product_name_zh, s.sector_name_zh, ld.disbursed_amount FROM loan_drawdown ld JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN loan_product_catalog lpc ON lpc.product_code = ld.drawdown_type JOIN industry_sector s ON s.sector_code = a.target_industry_code WHERE lpc.is_working_capital = 1 AND s.risk_category = 'EXIT' AND ld.status = 'ACTIVE' ORDER BY ld.disbursed_amount DESC, ld.loan_id LIMIT 200;	bankreg_main
SELECT i.institution_name, p.display_name,        ROUND(SUM(lbs.principal_balance), 2) AS bal,        cs.net_capital,        ROUND(SUM(lbs.principal_balance) * 1.0 / cs.net_capital, 6) AS ratio FROM loan_balance_snapshot lbs JOIN loan_drawdown ld ON ld.loan_id = lbs.loan_id JOIN credit_agreement a ON a.agreement_id = ld.agreement_id JOIN party p ON p.party_id = a.borrower_party_id JOIN institution i ON i.institution_id = a.institution_id JOIN capital_snapshot cs ON cs.institution_id = i.institution_id WHERE p.party_type = 'CORPORATE' GROUP BY i.institution_id, i.institution_name, p.party_id, p.display_name, cs.net_capital HAVING SUM(lbs.principal_balance) * 1.0 / cs.net_capital > 0.10 ORDER BY ratio DESC, p.party_id LIMIT 200;	bankreg_main
WITH ia AS (   SELECT a.target_industry_code, AVG(a.annual_interest_rate) AS avg_rate   FROM credit_agreement a GROUP BY a.target_industry_code ) SELECT a.agreement_id, p.display_name, ROUND(a.annual_interest_rate,4) AS annual_rate,        ROUND(ia.avg_rate,4) AS industry_avg,        ROUND(a.annual_interest_rate*100 / ia.avg_rate - 100, 2) AS deviation_pct FROM credit_agreement a JOIN ia ON ia.target_industry_code=a.target_industry_code JOIN party p ON p.party_id=a.borrower_party_id WHERE a.annual_interest_rate > 1.1 * ia.avg_rate ORDER BY deviation_pct DESC, a.agreement_id;	bankreg_main
SELECT q.loan_id, q.inst_name, ROUND(q.principal_balance,2) AS bal,        ROUND(q.principal_balance*100.0/SUM(q.principal_balance) OVER (PARTITION BY q.inst_id),2) AS share FROM (SELECT a.institution_id inst_id, i.institution_name inst_name, ld.loan_id, lbs.principal_balance       FROM loan_balance_snapshot lbs JOIN loan_drawdown ld ON ld.loan_id=lbs.loan_id       JOIN credit_agreement a ON a.agreement_id=ld.agreement_id       JOIN institution i ON i.institution_id=a.institution_id) q ORDER BY q.inst_name, share DESC, q.loan_id LIMIT 300;	bankreg_main
SELECT ld.loan_id, ROUND(ld.disbursed_amount,2) AS disbursed_amount, ld.status,        ROUND(SUM(rs.principal_due),2) AS overdue_principal,        COUNT(*) AS overdue_installments FROM loan_drawdown ld JOIN repayment_schedule rs ON rs.loan_id=ld.loan_id WHERE ld.status='ACTIVE' AND rs.status='OVERDUE' GROUP BY ld.loan_id, ld.disbursed_amount, ld.status HAVING COUNT(*) >= 2 ORDER BY overdue_installments DESC, overdue_principal DESC, ld.loan_id;	bankreg_main
SELECT a.loan_account_id, a.disbursed_on, COUNT(DISTINCT a.loan_id) AS cnt FROM loan_drawdown a JOIN loan_drawdown b   ON b.loan_account_id=a.loan_account_id AND b.disbursed_on=a.disbursed_on AND b.loan_id<>a.loan_id GROUP BY a.loan_account_id, a.disbursed_on HAVING COUNT(DISTINCT a.loan_id)>=2 ORDER BY cnt DESC, a.loan_account_id LIMIT 200;	bankreg_main
SELECT g.security_id, g.guaranteed_amount FROM guarantor_commitment g WHERE g.status = 'EXPIRED' ORDER BY g.guaranteed_amount DESC, g.security_id;	bankreg_main
SELECT bucket, COUNT(*) AS cnt FROM (   SELECT CASE WHEN julianday(ld.current_maturity_on)-julianday('2026-06-30')<0 THEN '已到期'               WHEN julianday(ld.current_maturity_on)-julianday('2026-06-30')<=90 THEN '临期'               ELSE '常态' END AS bucket   FROM loan_drawdown ld ) GROUP BY bucket ORDER BY CASE bucket WHEN '常态' THEN 1 WHEN '临期' THEN 2 ELSE 3 END;	bankreg_main
SELECT lk.collateral_id, COUNT(*) AS uses FROM collateral_link lk WHERE lk.status = 'ACTIVE' GROUP BY lk.collateral_id HAVING COUNT(*) > 1 ORDER BY uses DESC, lk.collateral_id;	bankreg_main
WITH rk AS (   SELECT d.loan_id, d.repayment_account_id, d.disbursed_on, d.disbursed_amount,          ROW_NUMBER() OVER (PARTITION BY d.repayment_account_id ORDER BY d.disbursed_on, d.loan_id) AS rn,          COUNT(*) OVER (PARTITION BY d.repayment_account_id) AS loan_cnt   FROM loan_drawdown d ) SELECT r.repayment_account_id, r.loan_id, r.disbursed_on, ROUND(r.disbursed_amount,2) AS amount, r.loan_cnt FROM rk r WHERE r.loan_cnt >= 3 AND r.rn <= 2 ORDER BY r.repayment_account_id, r.disbursed_on;	bankreg_main
SELECT i.institution_name, COUNT(*) AS frozen_cnt, ROUND(SUM(s.ledger_balance - s.available_balance), 2) AS frozen_amt FROM account_balance_snapshot s JOIN account a ON a.account_id = s.account_id JOIN institution i ON i.institution_id = a.institution_id WHERE (s.ledger_balance - s.available_balance) > 5000000 GROUP BY i.institution_id, i.institution_name ORDER BY frozen_amt DESC;	bankreg_main
SELECT t.account_id, t.opening_principal, t.maturity_on, t.annual_interest_rate FROM term_deposit t JOIN account a ON a.account_id = t.account_id WHERE a.status = 'ACTIVE' AND t.maturity_on < '2026-06-30' ORDER BY t.maturity_on, t.account_id;	bankreg_main
SELECT pc.card_id,        pc.card_type,        pc.issued_on FROM payment_card pc WHERE pc.card_type = 'DEBIT'   AND pc.status = 'ACTIVE'   AND pc.issued_on <= '2025-01-31' ORDER BY pc.issued_on, pc.card_id;	bankreg_main
WITH ratio AS (   SELECT i.institution_name,          ROUND(SUM(CASE WHEN d.payment_mode='ENTRUSTED_PAYMENT' THEN d.disbursed_amount ELSE 0 END),2) AS entrusted_amt,          ROUND(SUM(CASE WHEN d.payment_mode='SELF_PAYMENT' THEN d.disbursed_amount ELSE 0 END),2) AS self_amt   FROM loan_drawdown d   JOIN credit_agreement a ON a.agreement_id=d.agreement_id   JOIN institution i ON i.institution_id=a.institution_id   GROUP BY i.institution_name ) SELECT institution_name, entrusted_amt, self_amt,        ROUND(entrusted_amt * 1.0 / (entrusted_amt + self_amt), 4) AS entrusted_ratio FROM ratio WHERE entrusted_amt * 1.0 / (entrusted_amt + self_amt) < 0.52 ORDER BY entrusted_ratio, institution_name;	bankreg_main
WITH share AS (   SELECT d.agreement_id, d.loan_id, ROUND(d.disbursed_amount,2) AS amount,          ROUND(SUM(d.disbursed_amount) OVER (PARTITION BY d.agreement_id),2) AS agg_total   FROM loan_drawdown d ) SELECT s.agreement_id, s.loan_id, s.amount, s.agg_total,        ROUND(s.amount * 100.0 / s.agg_total, 2) AS pct_share FROM share s WHERE s.amount * 100.0 / s.agg_total > 90 ORDER BY s.agreement_id, s.loan_id;	bankreg_main
SELECT i.institution_name,        ROUND(SUM(wp.actual_raise_amount),2) AS actual,        ROUND(SUM(CASE WHEN wp.status='ON_SALE' THEN wp.planned_raise_amount ELSE 0 END),2) AS planned,        ROUND(SUM(wp.actual_raise_amount)*1.0/NULLIF(SUM(CASE WHEN wp.status='ON_SALE' THEN wp.planned_raise_amount ELSE 0 END),0),4) AS ratio FROM wealth_product wp JOIN institution i ON i.institution_id=wp.issuer_institution_id GROUP BY i.institution_id, i.institution_name HAVING SUM(wp.actual_raise_amount)*1.0/NULLIF(SUM(CASE WHEN wp.status='ON_SALE' THEN wp.planned_raise_amount ELSE 0 END),0)>1.2 ORDER BY ratio DESC, i.institution_name;	bankreg_main
SELECT ld.loan_id, ld.disbursed_on, a.agreement_id, a.signed_on, ROUND(ld.disbursed_amount,2) AS amount FROM loan_drawdown ld JOIN credit_agreement a ON a.agreement_id=ld.agreement_id WHERE ld.disbursed_on < a.signed_on ORDER BY ld.loan_id;	bankreg_main
SELECT ld.loan_id, ld.disbursed_on, ac.account_id, ac.opened_on FROM loan_drawdown ld JOIN account ac ON ac.account_id=ld.disbursement_account_id WHERE ld.disbursed_on < ac.opened_on ORDER BY ld.disbursed_on, ld.loan_id;	bankreg_main
SELECT a.agreement_id, a.security_type, ROUND(a.contract_amount,2) AS contract_amount,        p.display_name FROM credit_agreement a JOIN party p ON p.party_id=a.borrower_party_id WHERE a.security_type='CREDIT' AND a.contract_amount > 8000000 ORDER BY contract_amount DESC, a.agreement_id;	bankreg_main
WITH borrowers AS (   SELECT DISTINCT borrower_party_id AS pid FROM credit_agreement ) SELECT pr.source_party_id AS 甲方编号, pr.target_party_id AS 乙方编号,        rc.relation_name_zh AS 关联关系名称 FROM party_relation pr JOIN relation_type_catalog rc ON rc.relation_type = pr.relation_type JOIN borrowers b1 ON b1.pid = pr.source_party_id JOIN borrowers b2 ON b2.pid = pr.target_party_id WHERE rc.relation_name_zh <> '非关联方' ORDER BY rc.relation_name_zh, pr.relation_id;	bankreg_main
SELECT eg.group_name, COUNT(DISTINCT egm.party_id) AS members,        ROUND(SUM(lbs.principal_balance),2) AS bal, ROUND(cs.net_capital,2) AS cap,        ROUND(SUM(lbs.principal_balance)*1.0/cs.net_capital,6) AS ratio FROM exposure_group eg JOIN exposure_group_member egm ON egm.exposure_group_id=eg.exposure_group_id JOIN credit_agreement a ON a.borrower_party_id=egm.party_id AND a.institution_id=eg.institution_id JOIN loan_drawdown ld ON ld.agreement_id=a.agreement_id JOIN loan_balance_snapshot lbs ON lbs.loan_id=ld.loan_id JOIN capital_snapshot cs ON cs.institution_id=eg.institution_id GROUP BY eg.exposure_group_id, eg.group_name HAVING COUNT(DISTINCT egm.party_id)>=2 AND SUM(lbs.principal_balance)*1.0/cs.net_capital>0.1 ORDER BY ratio DESC, eg.group_name LIMIT 200;	bankreg_main
SELECT pf.display_name AS 付款方姓名, pt.display_name AS 收款方姓名,        COUNT(*) AS 转账笔数,        ROUND(SUM(pe.amount), 2) AS 转账金额合计 FROM payment_event pe JOIN account_holder hf ON hf.account_id = pe.from_account_id AND hf.holder_role = 'PRIMARY' JOIN party pf ON pf.party_id = hf.party_id JOIN account_holder ht ON ht.account_id = pe.to_account_id AND ht.holder_role = 'PRIMARY' JOIN party pt ON pt.party_id = ht.party_id JOIN party_relation pr ON ((pr.source_party_id = hf.party_id AND pr.target_party_id = ht.party_id)                         OR (pr.source_party_id = ht.party_id AND pr.target_party_id = hf.party_id)) JOIN relation_type_catalog rc ON rc.relation_type = pr.relation_type WHERE rc.relation_name_zh <> '非关联方' GROUP BY pf.display_name, pt.display_name, hf.party_id, ht.party_id ORDER BY 转账金额合计 DESC, hf.party_id, ht.party_id;	bankreg_main
SELECT wp.product_id, wp.product_name, ma.asset_name FROM wealth_product wp JOIN product_holding_snapshot ph ON ph.product_id = wp.product_id JOIN managed_asset ma ON ma.asset_id = ph.asset_id WHERE ph.investment_path = 'NESTED_SPV' AND wp.risk_level = 'R5' AND wp.status = 'ON_SALE' ORDER BY wp.product_id, ma.asset_id;	bankreg_main
SELECT eg.exposure_group_id AS 集团编号, eg.group_name AS 集团名称,        COUNT(DISTINCT a.institution_id) AS 涉及机构数,        COUNT(DISTINCT egm.party_id) AS 授信成员数 FROM exposure_group eg JOIN exposure_group_member egm ON egm.exposure_group_id = eg.exposure_group_id JOIN credit_agreement a ON a.borrower_party_id = egm.party_id GROUP BY eg.exposure_group_id, eg.group_name HAVING COUNT(DISTINCT a.institution_id) >= 2 ORDER BY 涉及机构数 DESC, eg.exposure_group_id;	bankreg_main
WITH grp_ovd AS (   SELECT egm.exposure_group_id AS gid,          COUNT(DISTINCT egm.party_id) AS ovd_members,          ROUND(SUM(lbs.overdue_principal), 2) AS ovd_amount   FROM exposure_group_member egm   JOIN credit_agreement a ON a.borrower_party_id = egm.party_id   JOIN loan_drawdown ld ON ld.agreement_id = a.agreement_id   JOIN loan_balance_snapshot lbs ON lbs.loan_id = ld.loan_id   WHERE lbs.overdue_principal > 0   GROUP BY egm.exposure_group_id ) SELECT eg.exposure_group_id AS 集团编号, eg.group_name AS 集团名称,        g.ovd_members AS 逾期成员数, g.ovd_amount AS 逾期本金合计 FROM grp_ovd g JOIN exposure_group eg ON eg.exposure_group_id = g.gid ORDER BY g.ovd_amount DESC, eg.exposure_group_id;	bankreg_main
SELECT p.display_name AS 员工姓名, so.operator_id AS 操作员编号,        so.authority_level AS 权限级别, COUNT(DISTINCT a.agreement_id) AS 自贷合同数 FROM service_operator so JOIN staff_member sm ON sm.staff_id = so.staff_id JOIN party p ON p.party_id = sm.person_party_id JOIN credit_agreement a ON a.borrower_party_id = p.party_id WHERE so.operator_kind = 'CREDIT_OFFICER' GROUP BY p.display_name, so.operator_id, sm.person_party_id, so.authority_level ORDER BY 自贷合同数 DESC, so.operator_id;	bankreg_main
SELECT p.display_name AS 员工姓名, ld.loan_id AS 借据编号,        ROUND(ld.disbursed_amount, 2) AS 放款金额, ld.disbursed_on AS 放款日期 FROM loan_drawdown ld JOIN account ac ON ac.account_id = ld.disbursement_account_id JOIN account_holder ah ON ah.account_id = ac.account_id AND ah.holder_role = 'PRIMARY' JOIN party p ON p.party_id = ah.party_id AND p.party_type = 'STAFF' ORDER BY ld.disbursed_amount DESC, ld.loan_id;	bankreg_main
WITH borrower_due AS (   SELECT a.borrower_party_id, SUM(rs.principal_due + rs.interest_due) AS total_due   FROM repayment_schedule rs   JOIN loan_drawdown ld ON ld.loan_id = rs.loan_id   JOIN credit_agreement a ON a.agreement_id = ld.agreement_id   GROUP BY a.borrower_party_id ) SELECT p.display_name AS 借款人姓名, pp.party_id AS 客户编号,        ROUND(pp.annual_income, 2) AS 年收入,        ROUND(bd.total_due, 2) AS 应还本息总额,        ROUND(bd.total_due / pp.annual_income, 2) AS 占年收入倍数 FROM borrower_due bd JOIN person_profile pp ON pp.party_id = bd.borrower_party_id JOIN party p ON p.party_id = pp.party_id ORDER BY 占年收入倍数 DESC, pp.party_id LIMIT 50;	bankreg_main
SELECT r.loan_id, COUNT(*) AS 逾期期数, ROUND(SUM(r.principal_due), 2) AS 逾期本金合计 FROM repayment_schedule r WHERE r.status = 'OVERDUE' GROUP BY r.loan_id HAVING SUM(r.principal_due) > 120000000 ORDER BY 逾期本金合计 DESC, r.loan_id;	bankreg_main
SELECT cf.facility_type, COUNT(*) AS 记录数 FROM credit_facility cf WHERE cf.limit_amount > 300000000 GROUP BY cf.facility_type ORDER BY 记录数 DESC, cf.facility_type;	bankreg_main
SELECT pm.payment_mode_name_zh AS 支付方式, COUNT(*) AS 记录数 FROM loan_drawdown ld JOIN payment_mode_catalog pm ON pm.payment_mode = ld.payment_mode GROUP BY pm.payment_mode_name_zh ORDER BY 记录数 DESC, pm.payment_mode_name_zh;	bankreg_main
SELECT pm.payment_mode_name_zh AS 支付方式, COUNT(*) AS 待执行指令数量 FROM payment_instruction pi JOIN payment_mode_catalog pm ON pm.payment_mode = pi.payment_mode WHERE pi.status = 'PENDING' GROUP BY pm.payment_mode_name_zh ORDER BY 待执行指令数量 DESC, pm.payment_mode_name_zh;	bankreg_main
select rc.loan_id, g.grade_name_zh, d.principal_overdue_days, d.overdue_principal from risk_classification rc join classification_grade g on g.grade_code = rc.grade_code join delinquency_snapshot d on d.loan_id = rc.loan_id where g.grade_name_zh = '正常' and d.principal_overdue_days > 30 order by d.principal_overdue_days desc, rc.loan_id	bankreg_main
SELECT p.customer_segment AS seg, COUNT(*) AS cnt FROM person_profile pp JOIN party p ON p.party_id = pp.party_id WHERE pp.annual_income > 1000000 GROUP BY p.customer_segment ORDER BY cnt DESC, p.customer_segment;	bankreg_main
SELECT ma.asset_category_primary,        COUNT(*) AS cnt FROM managed_asset ma JOIN industry_sector isec ON isec.sector_code = ma.industry_code WHERE isec.risk_category = 'RESTRICTED' GROUP BY ma.asset_category_primary HAVING COUNT(*) < 33 ORDER BY cnt DESC, ma.asset_category_primary;	bankreg_main
SELECT h.party_id, COUNT(*) AS n, ROUND(SUM(e.amount), 2) AS tot FROM payment_event e JOIN account a ON a.account_id = e.from_account_id JOIN payment_card c ON c.settlement_account_id = a.account_id JOIN card_type_catalog t ON t.card_type = c.card_type JOIN party h ON h.party_id = c.holder_party_id WHERE t.name_zh = '贷记卡' AND e.is_cash = 1 GROUP BY h.party_id HAVING COUNT(*) > 5 ORDER BY n DESC, tot DESC;	bankreg_main
SELECT c.holder_party_id, COUNT(*) AS cnt FROM payment_card c GROUP BY c.holder_party_id HAVING COUNT(*) > 3 ORDER BY cnt DESC, c.holder_party_id;	bankreg_main
SELECT t.name_zh AS card_type_name, COUNT(*) AS n,        ROUND(AVG(e.amount), 2) AS avg_amt FROM payment_event e JOIN account a ON a.account_id = e.from_account_id JOIN payment_card c ON c.settlement_account_id = a.account_id JOIN card_type_catalog t ON t.card_type = c.card_type WHERE t.name_zh IN ('贷记卡', '借记卡') AND e.is_cash = 1 GROUP BY t.card_type, t.name_zh ORDER BY avg_amt DESC, t.name_zh;	bankreg_main
WITH ranked AS (   SELECT cv.collateral_id, cv.valuation_amount,          ROW_NUMBER() OVER (PARTITION BY cv.collateral_id ORDER BY cv.valuation_amount DESC) AS rn,          COUNT(*) OVER (PARTITION BY cv.collateral_id) AS n   FROM collateral_valuation cv ) SELECT ca.collateral_id, ca.asset_label, ROUND(r.valuation_amount,2) AS val FROM ranked r JOIN collateral_asset ca ON ca.collateral_id=r.collateral_id WHERE r.rn=1 AND r.n>=2 ORDER BY val DESC, ca.collateral_id;	bankreg_main
select cl.collateral_id, ca.asset_label, count(*) as 押品使用次数,   count(distinct cl.security_id) as 关联担保数 from collateral_link cl join collateral_asset ca on ca.collateral_id = cl.collateral_id where cl.status = 'ACTIVE' group by cl.collateral_id, ca.asset_label having count(*) >= 2 order by 押品使用次数 desc, cl.collateral_id	bankreg_main
WITH agr_loan AS (   SELECT agreement_id, ROUND(SUM(disbursed_amount), 2) AS total_disbursed   FROM loan_drawdown   GROUP BY agreement_id ) SELECT gmt.guarantor_party_id, p.display_name, so.agreement_id,        gmt.guaranteed_amount, al.total_disbursed FROM guarantor_commitment gmt JOIN party p ON p.party_id = gmt.guarantor_party_id JOIN security_agreement sa ON sa.security_id = gmt.security_id JOIN secured_obligation so ON so.security_id = sa.security_id JOIN agr_loan al ON al.agreement_id = so.agreement_id WHERE gmt.status = 'ACTIVE' AND gmt.guaranteed_amount > al.total_disbursed ORDER BY gmt.guaranteed_amount DESC, gmt.guarantor_party_id, so.agreement_id;	bankreg_main
select a.borrower_party_id, l.loan_id, l.principal_balance as 贷款余额,   a.contract_amount as 授信金额, round(l.principal_balance / a.contract_amount, 2) as 余额倍数 from loan_balance_snapshot l join loan_drawdown ld on ld.loan_id = l.loan_id join credit_agreement a on a.agreement_id = ld.agreement_id where l.principal_balance >= 4.0 * a.contract_amount order by 余额倍数 desc, l.loan_id	bankreg_main
select i.institution_name, g.grade_name_zh, count(*) as 多计提笔数,   round(sum(ps.recognized_amount - ps.required_amount), 2) as 多计提金额 from provision_snapshot ps join risk_classification rc on rc.loan_id = ps.loan_id join classification_grade g on g.grade_code = rc.grade_code join loan_drawdown ld on ld.loan_id = ps.loan_id join credit_agreement a on a.agreement_id = ld.agreement_id join institution i on i.institution_id = a.institution_id where g.is_nonperforming = 1 and ps.recognized_amount > ps.required_amount group by i.institution_name, g.grade_name_zh order by 多计提金额 desc, i.institution_name, g.grade_name_zh	bankreg_main
SELECT ca.collateral_id, ca.asset_label,        MAX(CASE WHEN cv.valuation_type = 'INTERNAL' THEN cv.valuation_amount END) AS internal_val,        MAX(CASE WHEN cv.valuation_type = 'EXTERNAL' THEN cv.valuation_amount END) AS external_val,        ROUND(MAX(CASE WHEN cv.valuation_type = 'INTERNAL' THEN cv.valuation_amount END)            - MAX(CASE WHEN cv.valuation_type = 'EXTERNAL' THEN cv.valuation_amount END), 2) AS under_diff FROM collateral_asset ca JOIN collateral_valuation cv ON cv.collateral_id = ca.collateral_id WHERE cv.valuation_type IN ('INTERNAL', 'EXTERNAL') GROUP BY ca.collateral_id, ca.asset_label HAVING MAX(CASE WHEN cv.valuation_type = 'INTERNAL' THEN cv.valuation_amount END) IS NOT NULL    AND MAX(CASE WHEN cv.valuation_type = 'EXTERNAL' THEN cv.valuation_amount END) IS NOT NULL    AND MAX(CASE WHEN cv.valuation_type = 'EXTERNAL' THEN cv.valuation_amount END)      < MAX(CASE WHEN cv.valuation_type = 'INTERNAL' THEN cv.valuation_amount END) ORDER BY MAX(CASE WHEN cv.valuation_type = 'INTERNAL' THEN cv.valuation_amount END)         - MAX(CASE WHEN cv.valuation_type = 'EXTERNAL' THEN cv.valuation_amount END) DESC, ca.collateral_id;	bankreg_main
SELECT sa.security_id, sa.secured_amount, COUNT(gc.commitment_id) AS guarantor_count,        ROUND(SUM(gc.guaranteed_amount), 2) AS total_guaranteed FROM security_agreement sa JOIN guarantor_commitment gc ON gc.security_id = sa.security_id WHERE gc.status = 'ACTIVE' GROUP BY sa.security_id, sa.secured_amount HAVING SUM(gc.guaranteed_amount) < sa.secured_amount ORDER BY SUM(gc.guaranteed_amount) DESC, sa.security_id;	bankreg_main
SELECT p.party_id, p.display_name, COUNT(DISTINCT egm.exposure_group_id) AS group_count FROM party_relation pr JOIN relation_type_catalog rc ON rc.relation_type = pr.relation_type JOIN party p ON p.party_id = pr.source_party_id JOIN exposure_group_member egm ON egm.party_id = p.party_id WHERE rc.relation_name_zh = '影子股东' GROUP BY p.party_id, p.display_name ORDER BY COUNT(DISTINCT egm.exposure_group_id) DESC, p.party_id;	bankreg_main
select ca.collateral_id, ca.asset_label, ca.collateral_type from collateral_asset ca where ca.status = 'ACTIVE'   and not exists (     select 1 from collateral_link cl     where cl.collateral_id = ca.collateral_id and cl.status = 'ACTIVE'   ) order by ca.collateral_id	bankreg_main
SELECT gc.guarantor_party_id AS party_id, p.display_name,        gc.guaranteed_amount AS guaranteed_amount,        gc.status AS guarantor_status FROM guarantor_commitment gc JOIN party p ON p.party_id = gc.guarantor_party_id WHERE gc.status = 'ACTIVE'   AND EXISTS (     SELECT 1     FROM credit_agreement a     JOIN loan_drawdown ld ON ld.agreement_id = a.agreement_id     JOIN delinquency_snapshot d ON d.loan_id = ld.loan_id AND d.principal_overdue_days > 0     WHERE a.borrower_party_id = gc.guarantor_party_id   ) ORDER BY gc.guaranteed_amount DESC, gc.guarantor_party_id;	bankreg_main
WITH dlq AS (SELECT ca.borrower_party_id AS party, ca.institution_id AS inst, SUM(d.overdue_principal) AS overdue FROM delinquency_snapshot d JOIN loan_drawdown ld ON ld.loan_id=d.loan_id JOIN credit_agreement ca ON ca.agreement_id=ld.agreement_id GROUP BY ca.borrower_party_id, ca.institution_id) SELECT wp.product_name, ma.asset_name, ma.obligor_party_id, ROUND(dlq.overdue,2) AS sum_overdue FROM product_holding_snapshot ph JOIN wealth_product wp ON wp.product_id=ph.product_id JOIN managed_asset ma ON ma.asset_id=ph.asset_id JOIN dlq ON dlq.party=ma.obligor_party_id AND dlq.overdue>0 AND dlq.inst=wp.issuer_institution_id JOIN party pc ON pc.party_id=ma.obligor_party_id AND pc.party_type='CORPORATE' WHERE ph.lookthrough_depth>=2 ORDER BY wp.product_name, sum_overdue DESC;	bankreg_main
SELECT a.agreement_id, p.display_name, a.contract_amount,        COUNT(DISTINCT cl.collateral_id) AS collateral_count,        COUNT(DISTINCT gc.guarantor_party_id) AS guarantor_count FROM credit_agreement a JOIN party p ON p.party_id = a.borrower_party_id JOIN secured_obligation so ON so.agreement_id = a.agreement_id JOIN security_agreement sa ON sa.security_id = so.security_id JOIN collateral_link cl ON cl.security_id = sa.security_id JOIN guarantor_commitment gc ON gc.security_id = sa.security_id WHERE sa.status = 'ACTIVE' GROUP BY a.agreement_id, p.display_name, a.contract_amount ORDER BY a.contract_amount DESC, a.agreement_id;	bankreg_main
SELECT wp.product_id, wp.product_name, SUM(ph.carrying_amount-ph.fair_value) AS inv_diff, COUNT(*) AS cnt FROM product_holding_snapshot ph JOIN wealth_product wp ON wp.product_id=ph.product_id WHERE ph.carrying_amount > ph.fair_value GROUP BY wp.product_id, wp.product_name HAVING SUM(ph.carrying_amount-ph.fair_value)>0 ORDER BY inv_diff DESC, wp.product_id;	bankreg_main
WITH dlq AS (SELECT ca.borrower_party_id AS party, ca.institution_id AS inst, SUM(d.overdue_principal) AS overdue, COUNT(DISTINCT ld.loan_id) AS nln FROM delinquency_snapshot d JOIN loan_drawdown ld ON ld.loan_id=d.loan_id JOIN credit_agreement ca ON ca.agreement_id=ld.agreement_id GROUP BY ca.borrower_party_id, ca.institution_id) SELECT wp.product_name, ma.asset_name, ph.lookthrough_depth, ROUND(ph.carrying_amount,2) AS carry, ROUND(dlq.overdue,2) AS overdue FROM product_holding_snapshot ph JOIN wealth_product wp ON wp.product_id=ph.product_id JOIN managed_asset ma ON ma.asset_id=ph.asset_id JOIN dlq ON dlq.party=ma.issuer_party_id AND dlq.overdue>0 AND dlq.inst=wp.issuer_institution_id WHERE ph.lookthrough_depth>=3 ORDER BY ph.lookthrough_depth DESC, ph.holding_id;	bankreg_main
SELECT cl.collateral_id,        SUM(CASE WHEN cl.lien_priority = 1 AND cl.status = 'ACTIVE' THEN 1 ELSE 0 END) AS first_lien_count,        SUM(CASE WHEN cl.lien_priority = 1 AND cl.status = 'ACTIVE' AND cl.pledge_ratio > 0.6 THEN 1 ELSE 0 END) AS high_ratio_count FROM collateral_link cl GROUP BY cl.collateral_id HAVING SUM(CASE WHEN cl.lien_priority = 1 AND cl.status = 'ACTIVE' AND cl.pledge_ratio > 0.6 THEN 1 ELSE 0 END) >= 2 ORDER BY SUM(CASE WHEN cl.lien_priority = 1 AND cl.status = 'ACTIVE' AND cl.pledge_ratio > 0.6 THEN 1 ELSE 0 END) DESC, cl.collateral_id;	bankreg_main
SELECT i.institution_name, ROUND(c.net_capital/f.total_assets,6) AS leverage_val FROM institution i JOIN capital_snapshot c ON c.institution_id=i.institution_id JOIN financial_snapshot f ON f.party_id='PTY-'||i.institution_id ORDER BY leverage_val DESC;	bankreg_main
SELECT m.valuation_method, ROUND(SUM(h.carrying_amount),2) AS carrying_total FROM product_holding_snapshot h JOIN managed_asset m ON m.asset_id=h.asset_id GROUP BY m.valuation_method ORDER BY carrying_total DESC;	bankreg_main
SELECT i.institution_name, COUNT(*) AS deposit_cnt, ROUND(SUM(td.opening_principal),2) AS principal_total FROM term_deposit td JOIN account a ON a.account_id=td.account_id JOIN institution i ON i.institution_id=a.institution_id GROUP BY i.institution_name ORDER BY principal_total DESC;	bankreg_main
SELECT so.authority_level,        COUNT(DISTINCT so.operator_id) AS ops,        COUNT(DISTINCT so.staff_id) AS staffs FROM service_operator so JOIN staff_member sm ON sm.staff_id = so.staff_id WHERE sm.employment_type = 'PERMANENT' GROUP BY so.authority_level HAVING COUNT(DISTINCT so.staff_id) >= 10 ORDER BY ops DESC, so.authority_level;	bankreg_main
SELECT i.institution_name, COUNT(*) AS due_cnt FROM term_deposit td JOIN account a ON a.account_id = td.account_id JOIN institution i ON i.institution_id = a.institution_id WHERE julianday(td.maturity_on) - julianday('2026-06-30') BETWEEN 0 AND 30 GROUP BY i.institution_id, i.institution_name ORDER BY due_cnt DESC, i.institution_name;	bankreg_main
SELECT g.grade_name_zh,        COUNT(*) AS cnt FROM risk_classification rc JOIN classification_grade g ON g.grade_code = rc.grade_code WHERE rc.classification_basis = 'MANUAL_REVIEW' GROUP BY g.grade_name_zh HAVING COUNT(*) BETWEEN 60 AND 105 ORDER BY cnt DESC, g.grade_name_zh;	bankreg_main
WITH sh AS (SELECT ca.institution_id AS institution_id, COUNT(DISTINCT ld.loan_id) AS npl_loan, SUM(d.overdue_principal) AS tot_od FROM delinquency_snapshot d JOIN loan_drawdown ld ON ld.loan_id=d.loan_id JOIN credit_agreement ca ON ca.agreement_id=ld.agreement_id WHERE d.principal_overdue_days>=90 GROUP BY ca.institution_id) SELECT cs.institution_id, sh.npl_loan, ROUND(sh.tot_od,2) AS tot_od FROM capital_snapshot cs JOIN sh ON sh.institution_id=cs.institution_id JOIN financial_snapshot f ON f.party_id='PTY-'||cs.institution_id WHERE sh.tot_od/f.annual_revenue>0.5 ORDER BY tot_od DESC;	bankreg_main
WITH lb AS (     SELECT ca.institution_id AS institution_id,            ROUND(SUM(lbs.principal_balance), 2) AS gross_loan     FROM loan_balance_snapshot lbs     JOIN loan_drawdown ld ON ld.loan_id = lbs.loan_id     JOIN credit_agreement ca ON ca.agreement_id = ld.agreement_id     WHERE ld.status = 'ACTIVE'     GROUP BY ca.institution_id ) SELECT i.institution_name AS institution_name,        lb.gross_loan AS gross_loan,        cs.risk_weighted_assets AS rwa,        ROUND(lb.gross_loan * 100.0 / cs.risk_weighted_assets, 2) AS loan_pct_rwa FROM lb JOIN institution i ON i.institution_id = lb.institution_id JOIN capital_snapshot cs ON cs.institution_id = lb.institution_id ORDER BY loan_pct_rwa DESC, i.institution_name;	bankreg_main
SELECT pi.payment_mode,        COUNT(*) AS cnt FROM payment_instruction pi JOIN loan_drawdown dd ON dd.loan_id = pi.loan_id WHERE pi.status = 'PENDING'   AND dd.status = 'ACTIVE' GROUP BY pi.payment_mode HAVING COUNT(*) > 45 ORDER BY cnt DESC, pi.payment_mode;	bankreg_main
SELECT i.institution_name,        COUNT(*) AS exception_cnt,        ROUND(SUM(q.amount_value), 2) AS exception_amount,        cs.net_capital,        f.total_assets,        ROUND(SUM(q.amount_value) * 100.0 / cs.net_capital, 4) AS pct_of_capital FROM prudential_metric_snapshot_v3 q JOIN institution i ON i.institution_id = q.institution_id JOIN capital_snapshot cs ON cs.institution_id = i.institution_id JOIN financial_snapshot f ON f.party_id = 'PTY-' || i.institution_id WHERE q.exception_flag = 1 GROUP BY i.institution_id, i.institution_name, cs.net_capital, f.total_assets HAVING COUNT(*) >= 8 ORDER BY pct_of_capital DESC, i.institution_name;	bankreg_main
WITH prov AS (     SELECT a.institution_id AS institution_id,            COUNT(DISTINCT ld.loan_id) AS shortfall_loans,            ROUND(SUM(ps.required_amount - ps.recognized_amount), 2) AS shortfall_amount     FROM provision_snapshot ps     JOIN loan_drawdown ld ON ld.loan_id = ps.loan_id     JOIN credit_agreement a ON a.agreement_id = ld.agreement_id     WHERE ps.recognized_amount < ps.required_amount     GROUP BY a.institution_id ) SELECT i.institution_name,        COUNT(*) AS overdue_submissions,        ROUND(AVG(r.amount_value), 2) AS avg_ledger_amount,        p.shortfall_loans,        p.shortfall_amount FROM regulatory_submission_event_v3 r JOIN institution i ON i.institution_id = r.institution_id JOIN prov p ON p.institution_id = r.institution_id WHERE r.completion_date IS NULL OR r.completion_date > r.deadline_date GROUP BY i.institution_name, p.shortfall_loans, p.shortfall_amount HAVING COUNT(*) >= 25 ORDER BY p.shortfall_amount DESC, i.institution_name;	bankreg_main
WITH fac AS (     SELECT institution_id AS institution_id, COUNT(*) AS active_facilities     FROM credit_facility     GROUP BY institution_id ) SELECT i.institution_name, f.active_facilities,        ROUND(SUM(CASE WHEN r.exception_flag = 1 THEN r.amount_value ELSE 0 END), 2) AS except_amount,        ROUND(AVG(r.ratio_value), 4) AS avg_ratio FROM governance_control_record_v3 r JOIN institution i ON i.institution_id = r.institution_id JOIN fac f ON f.institution_id = i.institution_id GROUP BY i.institution_id, i.institution_name, f.active_facilities HAVING SUM(CASE WHEN r.exception_flag = 1 THEN 1 ELSE 0 END) >= 5 ORDER BY except_amount DESC, i.institution_name;	bankreg_main
SELECT p.display_name,        COUNT(DISTINCT pr.target_party_id) AS counterparties,        COUNT(DISTINCT pr.relation_type) AS relation_kinds,        SUM(CASE WHEN rt.relation_name_zh <> '非关联方' THEN 1 ELSE 0 END) AS vetted_edges FROM related_transaction_record_v3 r JOIN party p ON p.party_id = r.subject_id JOIN party_relation pr ON pr.source_party_id = r.subject_id JOIN relation_type_catalog rt ON rt.relation_type = pr.relation_type WHERE r.exception_flag = 1 GROUP BY p.party_id, p.display_name ORDER BY counterparties DESC, relation_kinds DESC, p.display_name;	bankreg_main
WITH card_stat AS (     SELECT a.institution_id,            COUNT(DISTINCT pc.card_id) AS active_cards,            COUNT(DISTINCT pc.holder_party_id) AS card_holders     FROM payment_card pc     JOIN account a ON a.account_id = pc.settlement_account_id     WHERE pc.status = 'ACTIVE'     GROUP BY a.institution_id ), op_stat AS (     SELECT institution_id,            COUNT(*) AS active_op_records,            ROUND(SUM(CASE WHEN exception_flag = 1 THEN amount_value ELSE 0 END), 2) AS except_amount     FROM operational_risk_event_v3     WHERE status_code = 'ACTIVE'     GROUP BY institution_id     HAVING COUNT(*) >= 43 ) SELECT i.institution_name, c.active_cards, c.card_holders,        o.except_amount, o.active_op_records FROM op_stat o JOIN card_stat c ON c.institution_id = o.institution_id JOIN institution i ON i.institution_id = o.institution_id ORDER BY o.except_amount DESC, i.institution_name;	bankreg_main
